"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1072],{41378:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"XPSystemLoader","desc":"Gameplay-place entry point for the XP system. Initializes `XPManager`\\n(profile lifecycle + replication), then wires the two earning sources:\\n\\n- **Distance:** while the train is in its \\"go\\" state (running \u2014 not braked,\\n  not stalled), award `XPConfig.DISTANCE_XP_PER_TICK` to the whole party\\n  every `XPConfig.DISTANCE_TICK_SECONDS`. Go-state is read from\\n  `Signals.SetTrainState` (the train starts braked, so no XP accrues\\n  pre-start).\\n- **Kills:** award `XPConfig.KILL_XP` and `CoinConfig.KILL_COINS` to every\\n  player whenever an `EnemyNPC`-tagged model\'s Humanoid dies\\n  (attribution-agnostic \u2014 shared rewards; kill perks scale them per player).\\n\\nDo NOT run this in the lobby place; the lobby runs `XPManager.Initialize`\\nonly (for display + session handoff), without earners.","realm":["Server"],"source":{"line":21,"path":"src/ServerScriptService/XPSystemLoader.server.luau"}}')}}]);